 "content": "from collections import deque


def transform(grid):
    """Reflect the largest nonzero rectangular panel across its anti-diagonal."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(cells)
    panel = max(components, key=len)
    r0 = min(r for r, _ in panel)
    r1 = max(r for r, _ in panel)
    c0 = min(c for _, c in panel)
    c1 = max(c for _, c in panel)
    panel_h, panel_w = r1 - r0 + 1, c1 - c0 + 1
    out = [[0] * panel_h for _ in range(panel_w)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            out[panel_w - 1 - (c - c0)][panel_h - 1 - (r - r0)] = grid[r][c]
    return out
